INSERT INTO questions (id, category_id, difficulty, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, topic) VALUES ('java_easy_1', 'java', 'easy', 'Who is known as the father of the Java programming language?', 'James Gosling', 'Bjarne Stroustrup', 'Guido van Rossum', 'Dennis Ritchie', 0, 'James Gosling developed Java while working at Sun Microsystems in 1995.', 'Core Java Fundamentals') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text);
INSERT INTO questions (id, category_id, difficulty, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, topic) VALUES ('java_easy_2', 'java', 'easy', 'What is the file extension of a compiled Java bytecode file?', '.java', '.class', '.byte', '.exe', 1, 'Java source files (.java) are compiled by javac into platform-independent bytecode stored in .class files.', 'JVM & Memory Architecture') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text);
INSERT INTO questions (id, category_id, difficulty, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, topic) VALUES ('java_easy_3', 'java', 'easy', 'Which component of Java is responsible for running the compiled bytecode?', 'JDK', 'JVM (Java Virtual Machine)', 'JRE Compiler', 'JDB (Java Debugger)', 1, 'The JVM (Java Virtual Machine) executes compiled Java bytecode on the host operating system.', 'JVM & Memory Architecture') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text);
INSERT INTO questions (id, category_id, difficulty, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, topic) VALUES ('java_easy_4', 'java', 'easy', 'Which of the following is NOT a primitive data type in Java?', 'int', 'boolean', 'float', 'String', 3, 'String is a class (reference type) in Java, whereas int, boolean, and float are primitive types.', 'Core Java Fundamentals') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text);
INSERT INTO questions (id, category_id, difficulty, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, topic) VALUES ('java_easy_5', 'java', 'easy', 'Which keyword is used to create a new instance of a class in Java?', 'new', 'create', 'alloc', 'instanceof', 0, 'The ''new'' keyword dynamically allocates memory at runtime for a new object.', 'Core Java Fundamentals') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text);
INSERT INTO questions (id, category_id, difficulty, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, topic) VALUES ('java_easy_6', 'java', 'easy', 'What is the default value of an uninitialized boolean instance variable in Java?', 'true', 'false', 'null', '0', 1, 'Instance boolean variables in Java are automatically initialized to false by default.', 'Core Java Fundamentals') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text);
INSERT INTO questions (id, category_id, difficulty, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, topic) VALUES ('java_easy_7', 'java', 'easy', 'What is the correct syntax for the main method entry point in Java?', 'public static void main(String[] args)', 'public void main(String args[])', 'static void main(String[] args)', 'public static int main(String[] args)', 0, 'The JVM looks for ''public static void main(String[] args)'' as the entry point of standalone Java applications.', 'Exception Handling') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text);
INSERT INTO questions (id, category_id, difficulty, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, topic) VALUES ('java_easy_8', 'java', 'easy', 'Which keyword is used by a class to inherit properties and methods from another class?', 'implements', 'inherits', 'extends', 'super', 2, 'The ''extends'' keyword establishes inheritance between a subclass and its superclass.', 'Core Java Fundamentals') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text);
INSERT INTO questions (id, category_id, difficulty, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, topic) VALUES ('java_easy_9', 'java', 'easy', 'Which control loop in Java is guaranteed to execute its code block at least once?', 'for loop', 'while loop', 'do-while loop', 'for-each loop', 2, 'A do-while loop evaluates its exit condition at the bottom, so the body executes at least once.', 'OOP Principles') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text);
INSERT INTO questions (id, category_id, difficulty, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, topic) VALUES ('java_easy_10', 'java', 'easy', 'Which package is automatically imported into every Java program without an explicit import statement?', 'java.util', 'java.io', 'java.lang', 'java.net', 2, 'java.lang contains core classes such as Object, String, Math, and System and is imported by default.', 'Core Java Fundamentals') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text);
INSERT INTO questions (id, category_id, difficulty, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, topic) VALUES ('java_medium_11', 'java', 'medium', 'What is method overloading in Java?', 'Multiple methods with the same name but different parameters in the same class', 'Redefining a superclass method in a subclass with the same signature', 'Hiding a private method of another class', 'Changing only the return type of a method', 0, 'Method overloading allows multiple methods in the same class to share the same name provided their argument lists differ.', 'Core Java Fundamentals') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text);
INSERT INTO questions (id, category_id, difficulty, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, topic) VALUES ('java_medium_12', 'java', 'medium', 'What does the ''final'' keyword signify when applied to a Java class?', 'The class cannot be instantiated', 'The class cannot be subclassed (inherited from)', 'All methods in the class are automatically private', 'The class can only exist once in memory', 1, 'Declaring a class as ''final'' prevents other classes from extending it (e.g., java.lang.String).', 'Core Java Fundamentals') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text);
INSERT INTO questions (id, category_id, difficulty, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, topic) VALUES ('java_medium_13', 'java', 'medium', 'Which statement accurately describes String objects in Java?', 'String objects are mutable and can be resized in place', 'String objects are immutable; modifying them creates a new object', 'String objects are primitive types stored on the CPU stack', 'String objects can only contain ASCII characters', 1, 'Strings are immutable in Java. Any operation that appears to modify a String actually returns a new String instance.', 'Core Java Fundamentals') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text);
INSERT INTO questions (id, category_id, difficulty, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, topic) VALUES ('java_medium_14', 'java', 'medium', 'What is the primary purpose of the ''super'' keyword in Java?', 'To refer to the direct superclass members and constructor', 'To grant maximum access permissions to a variable', 'To mark a method as thread-safe', 'To instantiate an interface directly', 0, '''super'' is used within a subclass to refer to methods, fields, or the constructor of its immediate superclass.', 'Core Java Fundamentals') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text);
INSERT INTO questions (id, category_id, difficulty, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, topic) VALUES ('java_medium_15', 'java', 'medium', 'Which block in a try-catch structure is always executed, whether an exception occurs or not?', 'catch block', 'finally block', 'throw block', 'throws block', 1, 'The finally block always executes after try and catch blocks, making it ideal for resource cleanup.', 'Exception Handling') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text);
INSERT INTO questions (id, category_id, difficulty, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, topic) VALUES ('java_medium_16', 'java', 'medium', 'Which of the following is a checked exception in Java?', 'NullPointerException', 'ArrayIndexOutOfBoundsException', 'IOException', 'ArithmeticException', 2, 'IOException is a checked exception that must be declared with ''throws'' or caught in a ''try-catch'' block.', 'Exception Handling') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text);
INSERT INTO questions (id, category_id, difficulty, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, topic) VALUES ('java_medium_17', 'java', 'medium', 'How do you obtain the number of elements in a standard Java array named ''scores''?', 'scores.length()', 'scores.size()', 'scores.length', 'scores.count', 2, 'In Java, array length is a final public field, accessed without parentheses as ''scores.length''.', 'Core Java Fundamentals') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text);
INSERT INTO questions (id, category_id, difficulty, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, topic) VALUES ('java_medium_18', 'java', 'medium', 'What is ''autoboxing'' in Java?', 'Automatic conversion of a primitive type to its corresponding wrapper object', 'Automatic garbage collection of unused variables', 'Creating GUI windows automatically', 'Converting any object into a byte array', 0, 'Autoboxing is the automatic conversion the Java compiler makes between primitive types and their wrapper classes (e.g., int to Integer).', 'Core Java Fundamentals') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text);
INSERT INTO questions (id, category_id, difficulty, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, topic) VALUES ('java_medium_19', 'java', 'medium', 'Can an abstract class in Java have constructor methods?', 'Yes, called when a concrete subclass is instantiated', 'No, abstract classes can never have constructors', 'Only if all methods in the class are abstract', 'Only if the constructor is private', 0, 'Abstract classes can define constructors, which are invoked by subclass constructors via super() during instantiation.', 'Core Java Fundamentals') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text);
INSERT INTO questions (id, category_id, difficulty, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, topic) VALUES ('java_medium_20', 'java', 'medium', 'Which method is called by the Garbage Collector before reclaiming an object''s memory in classic Java?', 'destroy()', 'finalize()', 'clean()', 'dispose()', 1, 'The finalize() method on java.lang.Object is historically invoked by the garbage collector before discarding an object.', 'JVM & Memory Architecture') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text);
INSERT INTO questions (id, category_id, difficulty, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, topic) VALUES ('java_hard_21', 'java', 'hard', 'Where are Java object instances physically allocated at runtime?', 'On the Call Stack', 'In the Heap memory', 'In the CPU Cache', 'In the PermGen exclusively', 1, 'All Java object instances are allocated on the Heap memory, while references and local primitive variables reside on the Stack.', 'Core Java Fundamentals') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text);
INSERT INTO questions (id, category_id, difficulty, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, topic) VALUES ('java_hard_22', 'java', 'hard', 'What is the key difference between HashMap and ConcurrentHashMap?', 'ConcurrentHashMap allows concurrent reads and segment/bucket-level writes without locking the whole map', 'HashMap is synchronized by default whereas ConcurrentHashMap is not', 'ConcurrentHashMap does not allow key values', 'HashMap can only store strings', 0, 'ConcurrentHashMap achieves thread-safety with high concurrency by using bucket-level locking (CAS and synchronized nodes), unlike full synchronization.', 'Collections Framework') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text);
INSERT INTO questions (id, category_id, difficulty, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, topic) VALUES ('java_hard_23', 'java', 'hard', 'What does the ''volatile'' keyword guarantee in Java multithreading?', 'Atomicity of compound operations (e.g., count++)', 'Visibility of variable updates across all threads by reading directly from main memory', 'Thread sleep duration', 'Deadlock prevention', 1, 'volatile ensures memory visibility and prevents instruction reordering, guaranteeing reads/writes go directly to shared main memory.', 'Multithreading') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text);
INSERT INTO questions (id, category_id, difficulty, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, topic) VALUES ('java_hard_24', 'java', 'hard', 'What happens during Java Generics ''Type Erasure''?', 'Type parameters are replaced with their bounds or Object at compile time to maintain bytecode compatibility', 'Variables are deleted from memory after execution', 'Runtime types are converted into strings', 'All primitive types are erased', 0, 'Type erasure removes all generic type information during compilation, inserting casts where necessary for backwards compatibility.', 'Core Java Fundamentals') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text);
INSERT INTO questions (id, category_id, difficulty, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, topic) VALUES ('java_hard_25', 'java', 'hard', 'What does calling String.intern() accomplish?', 'Puts the string into the String Constant Pool or returns the canonical instance if already present', 'Converts the string into integer bytecode', 'Translates string encoding to UTF-16', 'Encrypts the string', 0, 'intern() ensures all identical strings share the exact same memory address inside the String Constant Pool.', 'Core Java Fundamentals') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text);
INSERT INTO questions (id, category_id, difficulty, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, topic) VALUES ('java_hard_26', 'java', 'hard', 'What is a ''fail-fast'' iterator in Java Collections?', 'An iterator that throws ConcurrentModificationException if the underlying collection is modified during iteration', 'An iterator that continues silently despite modifications', 'An iterator optimized for network transfers', 'An iterator that removes elements immediately', 0, 'Fail-fast iterators (such as ArrayList''s iterator) detect concurrent structural modifications and immediately throw ConcurrentModificationException.', 'Collections Framework') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text);
INSERT INTO questions (id, category_id, difficulty, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, topic) VALUES ('java_hard_27', 'java', 'hard', 'How do ''default'' methods in Java 8 interfaces solve the multiple inheritance problem of methods?', 'Classes must explicitly override conflicting default methods from multiple interfaces', 'The compiler randomly picks one interface', 'Interfaces cannot have default methods with the same name', 'Subclasses crash at runtime', 0, 'If a class inherits conflicting default methods from multiple interfaces, the compiler requires the class to explicitly override the method.', 'OOP Principles') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text);
INSERT INTO questions (id, category_id, difficulty, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, topic) VALUES ('java_hard_28', 'java', 'hard', 'What is the difference between Comparable and Comparator in Java?', 'Comparable provides natural ordering via compareTo(); Comparator provides custom ordering via compare()', 'Comparator is for numbers only; Comparable is for text', 'Comparable cannot be used with Collections.sort()', 'They are identical and interchangeable', 0, 'Comparable defines single natural ordering on the class itself (compareTo), whereas Comparator allows multiple independent ordering strategies (compare).', 'Core Java Fundamentals') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text);
INSERT INTO questions (id, category_id, difficulty, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, topic) VALUES ('java_hard_29', 'java', 'hard', 'What is the memory leak risk associated with static inner classes vs non-static inner classes?', 'Non-static inner classes hold an implicit reference to their enclosing outer class instance', 'Static inner classes consume more CPU cycles', 'Non-static inner classes are always stored in Metaspace', 'Static inner classes cannot be garbage collected', 0, 'A non-static inner class holds an invisible reference to its outer class, which can prevent the outer class from being garbage collected.', 'JVM & Memory Architecture') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text);
INSERT INTO questions (id, category_id, difficulty, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, topic) VALUES ('java_hard_30', 'java', 'hard', 'What is a phantom reference in Java (java.lang.ref.PhantomReference)?', 'A reference used for post-mortem cleanup after an object has been finalized and before its memory is freed', 'A pointer to hardware memory addresses', 'A reference that never gets garbage collected', 'A weak key inside HashMap', 0, 'Phantom references are enqueued only after objects are finalized, providing a safer alternative to finalize() for cleanup tracking.', 'Core Java Fundamentals') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text);
INSERT INTO questions (id, category_id, difficulty, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, topic) VALUES ('sql_easy_1', 'sql', 'easy', 'What does SQL stand for?', 'Structured Query Language', 'Simple Question Language', 'Sequential Query List', 'Standard Quantity Logic', 0, 'SQL stands for Structured Query Language, the ANSI standard language for relational databases.', 'Basic SQL Queries') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text);
INSERT INTO questions (id, category_id, difficulty, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, topic) VALUES ('sql_easy_2', 'sql', 'easy', 'Which SQL command is used to extract data from a database?', 'GET', 'OPEN', 'SELECT', 'FETCH', 2, 'The SELECT statement queries and retrieves records from database tables.', 'Basic SQL Queries') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text);
INSERT INTO questions (id, category_id, difficulty, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, topic) VALUES ('sql_easy_3', 'sql', 'easy', 'Which SQL clause filters records based on a specific condition?', 'WHERE', 'FILTER', 'HAVING ONLY', 'CHECK', 0, 'The WHERE clause restricts rows returned to those satisfying the specified condition.', 'Basic SQL Queries') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text);
INSERT INTO questions (id, category_id, difficulty, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, topic) VALUES ('sql_easy_4', 'sql', 'easy', 'Which SQL keyword eliminates duplicate rows from a query result?', 'UNIQUE', 'DISTINCT', 'DIFFERENT', 'FILTER_DUPLICATES', 1, 'SELECT DISTINCT returns only unique values, eliminating duplicates from output.', 'Basic SQL Queries') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text);
INSERT INTO questions (id, category_id, difficulty, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, topic) VALUES ('sql_easy_5', 'sql', 'easy', 'Which aggregate function returns the total count of rows matching criteria?', 'SUM()', 'TOTAL()', 'COUNT()', 'NUM()', 2, 'COUNT() returns the number of rows matching the query criteria.', 'Aggregation & Grouping') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text);
INSERT INTO questions (id, category_id, difficulty, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, topic) VALUES ('sql_easy_6', 'sql', 'easy', 'Which clause is used to sort the result-set in SQL?', 'SORT BY', 'ORDER BY', 'GROUP BY', 'ARRANGE', 1, 'ORDER BY sorts the query result in ascending (ASC) or descending (DESC) order.', 'Basic SQL Queries') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text);
INSERT INTO questions (id, category_id, difficulty, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, topic) VALUES ('sql_easy_7', 'sql', 'easy', 'Which SQL statement adds new rows into a table?', 'ADD RECORD', 'INSERT INTO', 'NEW ROW', 'CREATE ROW', 1, 'The INSERT INTO statement is used to insert new records into a table.', 'DDL & Schema Design') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text);
INSERT INTO questions (id, category_id, difficulty, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, topic) VALUES ('sql_easy_8', 'sql', 'easy', 'Which constraint uniquely identifies each record in a database table?', 'FOREIGN KEY', 'PRIMARY KEY', 'CHECK', 'DEFAULT', 1, 'A PRIMARY KEY uniquely identifies each record and cannot contain NULL values.', 'DDL & Schema Design') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text);
INSERT INTO questions (id, category_id, difficulty, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, topic) VALUES ('sql_easy_9', 'sql', 'easy', 'Which SQL statement modifies existing records within a table?', 'MODIFY', 'UPDATE', 'SAVE', 'ALTER', 1, 'The UPDATE statement modifies existing data rows in a table.', 'DDL & Schema Design') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text);
INSERT INTO questions (id, category_id, difficulty, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, topic) VALUES ('sql_easy_10', 'sql', 'easy', 'Which command completely removes an entire table and its schema from the database?', 'DELETE TABLE', 'REMOVE TABLE', 'DROP TABLE', 'CLEAR TABLE', 2, 'DROP TABLE deletes the table definition along with all its data, triggers, and constraints.', 'DDL & Schema Design') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text);
INSERT INTO questions (id, category_id, difficulty, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, topic) VALUES ('sql_medium_11', 'sql', 'medium', 'What is the difference between WHERE and HAVING clauses in SQL?', 'WHERE filters rows before aggregation; HAVING filters aggregated groups after GROUP BY', 'WHERE is only for numbers; HAVING is for strings', 'HAVING cannot be used without WHERE', 'They are identical in SQL', 0, 'WHERE filters rows before any aggregate functions are applied; HAVING filters groups after GROUP BY.', 'Aggregation & Grouping') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text);
INSERT INTO questions (id, category_id, difficulty, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, topic) VALUES ('sql_medium_12', 'sql', 'medium', 'Which JOIN returns all rows from the left table and matched rows from the right table?', 'INNER JOIN', 'LEFT JOIN (or LEFT OUTER JOIN)', 'RIGHT JOIN', 'FULL JOIN', 1, 'A LEFT JOIN returns all records from the left table and matched records from the right table, filling nulls if no match.', 'SQL Joins') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text);
INSERT INTO questions (id, category_id, difficulty, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, topic) VALUES ('sql_medium_13', 'sql', 'medium', 'In a SQL LIKE pattern, which wildcard matches any string of zero or more characters?', '_', '%', '*', '?', 1, '% represents zero, one, or multiple characters, while _ represents exactly one character.', 'Basic SQL Queries') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text);
INSERT INTO questions (id, category_id, difficulty, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, topic) VALUES ('sql_medium_14', 'sql', 'medium', 'What does the TRUNCATE TABLE command do compared to DELETE FROM table?', 'TRUNCATE is a DDL command that quickly resets the table without logging individual row deletions', 'TRUNCATE only deletes the last row', 'DELETE drops the schema entirely', 'TRUNCATE is slower than DELETE', 0, 'TRUNCATE is a fast, minimally logged DDL operation that deallocates data pages rather than logging each row deletion.', 'DDL & Schema Design') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text);
INSERT INTO questions (id, category_id, difficulty, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, topic) VALUES ('sql_medium_15', 'sql', 'medium', 'Which SQL constraint prevents invalid data from being inserted by enforcing a boolean condition?', 'CHECK', 'NOT NULL', 'UNIQUE', 'FOREIGN KEY', 0, 'The CHECK constraint ensures that values in a column satisfy a specific boolean condition (e.g., age >= 18).', 'Basic SQL Queries') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text);
INSERT INTO questions (id, category_id, difficulty, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, topic) VALUES ('sql_medium_16', 'sql', 'medium', 'What does a FOREIGN KEY constraint ensure?', 'Referential integrity between records in two relational tables', 'Encryption of sensitive records', 'Automatic sorting by foreign column', 'Faster cloud backups', 0, 'A FOREIGN KEY enforces referential integrity by requiring that a value matches an existing primary key in another table.', 'Basic SQL Queries') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text);
INSERT INTO questions (id, category_id, difficulty, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, topic) VALUES ('sql_medium_17', 'sql', 'medium', 'How do you check for missing/unassigned values in a SQL column?', 'column = NULL', 'column IS NULL', 'column == NULL', 'column EQUALS NULL', 1, 'In SQL, NULL signifies unknown value and cannot be compared with ''=''; you must use ''IS NULL'' or ''IS NOT NULL''.', 'Basic SQL Queries') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text);
INSERT INTO questions (id, category_id, difficulty, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, topic) VALUES ('sql_medium_18', 'sql', 'medium', 'What is the difference between UNION and UNION ALL?', 'UNION removes duplicate rows from the combined result; UNION ALL keeps all duplicates', 'UNION is for numbers only; UNION ALL is for text', 'UNION ALL is slower than UNION', 'UNION sorts descending automatically', 0, 'UNION performs a distinct sort to eliminate duplicate rows, while UNION ALL retains all rows and is faster.', 'Basic SQL Queries') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text);
INSERT INTO questions (id, category_id, difficulty, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, topic) VALUES ('sql_medium_19', 'sql', 'medium', 'Which clause is used to group rows that have the same values in specified columns?', 'CLUSTER BY', 'GROUP BY', 'CATEGORY BY', 'PARTITION BY', 1, 'GROUP BY summarizes rows with identical values into summary rows (e.g., COUNT by department).', 'Basic SQL Queries') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text);
INSERT INTO questions (id, category_id, difficulty, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, topic) VALUES ('sql_medium_20', 'sql', 'medium', 'What does an INNER JOIN return?', 'Only rows that have matching values in both tables', 'All rows from both tables unconditionally', 'Only unmatched rows', 'Only the first 10 rows', 0, 'INNER JOIN selects records that have matching values in both tables based on the join predicate.', 'SQL Joins') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text);
INSERT INTO questions (id, category_id, difficulty, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, topic) VALUES ('sql_hard_21', 'sql', 'hard', 'What do the ACID properties in database transaction management stand for?', 'Atomicity, Consistency, Isolation, Durability', 'Availability, Correctness, Integrity, Distribution', 'Access, Concurrency, Indexing, Decoupling', 'Association, Control, Idempotence, Division', 0, 'ACID guarantees that database transactions are processed reliably: Atomicity, Consistency, Isolation, and Durability.', 'Transactions & ACID') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text);
INSERT INTO questions (id, category_id, difficulty, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, topic) VALUES ('sql_hard_22', 'sql', 'hard', 'What is the key benefit of a database B-Tree index?', 'Reduces search complexity from O(N) full table scan to O(log N) tree lookup', 'Automatically normalizes database tables', 'Encrypts disk tables automatically', 'Replaces SQL primary keys', 0, 'B-Tree indexes maintain sorted data to provide logarithmic O(log N) lookup, insertion, and range queries.', 'Indexes & Performance') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text);
INSERT INTO questions (id, category_id, difficulty, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, topic) VALUES ('sql_hard_23', 'sql', 'hard', 'What is a ''deadlock'' in a relational database?', 'A state where two or more transactions each hold locks that the other needs, causing mutual waiting', 'A corrupted table index on disk', 'A query that runs out of memory', 'A network disconnection', 0, 'A deadlock occurs when two transactions wait indefinitely for locks held by each other, resolved by the database aborting one.', 'Basic SQL Queries') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text);
INSERT INTO questions (id, category_id, difficulty, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, topic) VALUES ('sql_hard_24', 'sql', 'hard', 'What is a Window Function in SQL (e.g., ROW_NUMBER() OVER (...))?', 'A function that performs calculations across a set of rows related to the current row without collapsing them into one row', 'A function that opens desktop windows in the OS', 'A function limited to 10 rows maximum', 'A temporary table storage method', 0, 'Window functions compute values over partitions of rows while preserving each individual row''s identity.', 'Basic SQL Queries') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text);
INSERT INTO questions (id, category_id, difficulty, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, topic) VALUES ('sql_hard_25', 'sql', 'hard', 'What is the fundamental difference between 2nd Normal Form (2NF) and 3rd Normal Form (3NF)?', '2NF removes partial key dependencies; 3NF removes transitive dependencies', '2NF is for primary keys only; 3NF is for foreign keys', '2NF requires XML; 3NF requires JSON', 'There is no practical difference', 0, '2NF eliminates partial dependencies on a composite key, while 3NF eliminates transitive dependencies between non-key columns.', 'Basic SQL Queries') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text);
INSERT INTO questions (id, category_id, difficulty, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, topic) VALUES ('sql_hard_26', 'sql', 'hard', 'What is the difference between a standard View and a Materialized View?', 'A standard View is a saved query executed dynamically; a Materialized View stores query results physically on disk', 'A Materialized View cannot be queried using SELECT', 'Standard Views only work with MySQL', 'Materialized Views are stored only in RAM', 0, 'Standard views are virtual queries run on demand; materialized views physically persist result sets to optimize read-heavy workloads.', 'Basic SQL Queries') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text);
INSERT INTO questions (id, category_id, difficulty, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, topic) VALUES ('sql_hard_27', 'sql', 'hard', 'What transaction isolation level prevents Dirty Reads, Non-Repeatable Reads, and Phantom Reads?', 'SERIALIZABLE', 'READ COMMITTED', 'READ UNCOMMITTED', 'REPEATABLE READ', 0, 'SERIALIZABLE is the strictest isolation level, preventing dirty reads, non-repeatable reads, and phantom reads.', 'Transactions & ACID') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text);
INSERT INTO questions (id, category_id, difficulty, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, topic) VALUES ('sql_hard_28', 'sql', 'hard', 'What does the EXPLAIN ANALYZE command do in modern SQL engines (PostgreSQL/MySQL)?', 'Executes the query and outputs the actual execution plan with node costs, scan types, and timing', 'Automatically rewrites SQL code', 'Deletes slow rows', 'Creates missing indexes automatically', 0, 'EXPLAIN ANALYZE displays the optimizer''s execution plan alongside actual runtime statistics and cost profiles.', 'Basic SQL Queries') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text);
INSERT INTO questions (id, category_id, difficulty, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, topic) VALUES ('sql_hard_29', 'sql', 'hard', 'What is a composite clustered index?', 'A clustered index that orders physical table rows on disk based on multiple combined columns', 'An index stored on an external server', 'An index that cannot contain foreign keys', 'A temporary index created in memory', 0, 'A clustered index determines the physical order of data in the table; a composite clustered index sorts by multiple column keys.', 'Indexes & Performance') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text);
INSERT INTO questions (id, category_id, difficulty, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, topic) VALUES ('sql_hard_30', 'sql', 'hard', 'What is the purpose of the COALESCE() function in SQL?', 'Returns the first non-NULL value in a list of arguments', 'Combines multiple tables together', 'Converts text into uppercase', 'Calculates standard deviation', 0, 'COALESCE(val1, val2, ...) evaluates arguments in order and returns the first value that is not NULL.', 'Basic SQL Queries') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text);
INSERT INTO questions (id, category_id, difficulty, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, topic) VALUES ('html_css_easy_1', 'html_css', 'easy', 'What does HTML stand for?', 'HyperText Markup Language', 'High Tech Modern Language', 'Hyperlink and Text Marking Level', 'Home Tool Markup Language', 0, 'HTML stands for HyperText Markup Language, the standard markup language for documents on the Web.', 'HTML & CSS Basics') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text);
INSERT INTO questions (id, category_id, difficulty, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, topic) VALUES ('html_css_easy_2', 'html_css', 'easy', 'Which HTML tag is used to create a hyperlink?', '<link>', '<a>', '<href>', '<hyperlink>', 1, 'The <a> (anchor) tag creates hyperlinks that link to another page or resource.', 'HTML & CSS Basics') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text);
INSERT INTO questions (id, category_id, difficulty, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, topic) VALUES ('html_css_easy_3', 'html_css', 'easy', 'Which HTML tag represents the most important (largest) heading?', '<head>', '<h6>', '<h1>', '<heading>', 2, '<h1> represents top-level headings, while <h6> represents lowest-level headings.', 'HTML & CSS Basics') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text);
INSERT INTO questions (id, category_id, difficulty, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, topic) VALUES ('html_css_easy_4', 'html_css', 'easy', 'What does CSS stand for?', 'Creative Style Sheets', 'Cascading Style Sheets', 'Computer Style Syntax', 'Colorful Styling System', 1, 'CSS stands for Cascading Style Sheets, used to style and layout HTML documents.', 'HTML & CSS Basics') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text);
INSERT INTO questions (id, category_id, difficulty, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, topic) VALUES ('html_css_easy_5', 'html_css', 'easy', 'Which CSS property is used to set the text color of an element?', 'text-color', 'font-color', 'color', 'text-style', 2, 'The ''color'' property specifies the foreground color of text content.', 'HTML & CSS Basics') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text);
INSERT INTO questions (id, category_id, difficulty, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, topic) VALUES ('html_css_easy_6', 'html_css', 'easy', 'Which CSS symbol is used to select an element by its ID attribute?', '. (period)', '# (hash/pound)', '@ (at sign)', '* (asterisk)', 1, 'The ''#'' symbol targets elements with a specific id attribute (e.g. #header).', 'HTML & CSS Basics') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text);
INSERT INTO questions (id, category_id, difficulty, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, topic) VALUES ('html_css_easy_7', 'html_css', 'easy', 'In the CSS Box Model, which layer sits directly between content and border?', 'Margin', 'Padding', 'Outline', 'Gutter', 1, 'Padding clears an area around the content inside the element''s border.', 'CSS Box Model') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text);
INSERT INTO questions (id, category_id, difficulty, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, topic) VALUES ('html_css_easy_8', 'html_css', 'easy', 'Which CSS display property activates a modern flexible box layout?', 'display: block', 'display: inline', 'display: flex', 'display: table', 2, '''display: flex'' enables the Flexbox layout model for responsive alignment and distribution.', 'CSS Flexbox') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text);
INSERT INTO questions (id, category_id, difficulty, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, topic) VALUES ('html_css_easy_9', 'html_css', 'easy', 'Which HTML attribute specifies the image source path in an <img> tag?', 'href', 'src', 'url', 'link', 1, 'The ''src'' (source) attribute contains the path to the image file.', 'HTML & CSS Basics') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text);
INSERT INTO questions (id, category_id, difficulty, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, topic) VALUES ('html_css_easy_10', 'html_css', 'easy', 'Which CSS property adds transparent space outside an element''s border?', 'padding', 'margin', 'spacing', 'border-spacing', 1, 'Margin clears space outside the border of an element.', 'CSS Box Model') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text);
INSERT INTO questions (id, category_id, difficulty, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, topic) VALUES ('html_css_medium_11', 'html_css', 'medium', 'How does ''box-sizing: border-box'' change the CSS box model calculation?', 'Padding and border are included within the element''s specified width and height', 'Padding is added outside the element''s width', 'Borders are hidden automatically', 'Margins are subtracted from the width', 0, 'border-box ensures that padding and borders do not expand the element beyond its set width.', 'CSS Box Model') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text);
INSERT INTO questions (id, category_id, difficulty, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, topic) VALUES ('html_css_medium_12', 'html_css', 'medium', 'What is the difference between relative and absolute positioning in CSS?', 'Relative is positioned relative to its normal position; Absolute is positioned relative to its closest positioned ancestor', 'Relative removes elements from document flow; Absolute does not', 'Absolute positioning only works on tablet devices', 'They are identical', 0, 'position: relative offsets an element without removing it from flow; position: absolute positions relative to the nearest positioned ancestor.', 'HTML & CSS Basics') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text);
INSERT INTO questions (id, category_id, difficulty, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, topic) VALUES ('html_css_medium_13', 'html_css', 'medium', 'What is the semantic difference between <article> and <section> in HTML5?', '<article> represents a self-contained, independently distributable piece of content; <section> groups thematic content', '<section> is only for sidebar menus', '<article> cannot contain headings', 'They have no semantic distinction', 0, '<article> is intended for standalone content like blog posts, while <section> groups thematic subsections.', 'Semantic HTML5') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text);
INSERT INTO questions (id, category_id, difficulty, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, topic) VALUES ('html_css_medium_14', 'html_css', 'medium', 'In CSS Flexbox, what does ''justify-content'' control compared to ''align-items''?', 'justify-content aligns along the main axis; align-items aligns along the cross axis', 'justify-content only works vertically', 'align-items only works on mobile devices', 'They control the exact same axis', 0, 'justify-content aligns items along the primary flex direction; align-items controls alignment across the perpendicular cross axis.', 'CSS Flexbox') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text);
INSERT INTO questions (id, category_id, difficulty, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, topic) VALUES ('html_css_medium_15', 'html_css', 'medium', 'What unit is ''rem'' based on in CSS?', 'The font size of the root element (<html>)', 'The font size of the immediate parent element', 'The device screen height', 'The browser viewport width', 0, '''rem'' (root em) is relative to the font-size of the root <html> element, unlike ''em'' which is relative to the parent.', 'HTML & CSS Basics') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text);
INSERT INTO questions (id, category_id, difficulty, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, topic) VALUES ('html_css_medium_16', 'html_css', 'medium', 'Which CSS selector has the highest specificity?', '#main-header', '.nav-item.active', 'header nav a', '*', 0, 'An ID selector (#main-header, specificity 0-1-0-0) beats classes (0-0-1-0) and elements (0-0-0-1).', 'HTML & CSS Basics') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text);
INSERT INTO questions (id, category_id, difficulty, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, topic) VALUES ('html_css_medium_17', 'html_css', 'medium', 'Which CSS property creates a two-dimensional grid layout?', 'display: grid', 'display: flex', 'display: table-row', 'display: inline-block', 0, '''display: grid'' activates CSS Grid layout, allowing control over both rows and columns simultaneously.', 'CSS Grid') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text);
INSERT INTO questions (id, category_id, difficulty, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, topic) VALUES ('html_css_medium_18', 'html_css', 'medium', 'What does the '':nth-child(even)'' pseudo-class select?', 'Every element that is an even-numbered child of its parent', 'Every odd element', 'Only the 2nd child', 'Elements with even numbers of attributes', 0, ':nth-child(even) targets the 2nd, 4th, 6th, etc., siblings within their parent container.', 'HTML & CSS Basics') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text);
INSERT INTO questions (id, category_id, difficulty, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, topic) VALUES ('html_css_medium_19', 'html_css', 'medium', 'What is the purpose of the ''alt'' attribute on an <img> tag?', 'Provides alternative text for screen readers and when images fail to load', 'Styles the image border with alternative colors', 'Compresses image bandwidth', 'Rotates the image 180 degrees', 0, 'The alt attribute is essential for accessibility (screen readers) and displays text if the image fails to download.', 'HTML & CSS Basics') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text);
INSERT INTO questions (id, category_id, difficulty, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, topic) VALUES ('html_css_medium_20', 'html_css', 'medium', 'Which CSS media query targets screens with a maximum width of 768px?', '@media (max-width: 768px)', '@screen (width <= 768px)', '@media (width: 768px)', '@responsive (768px)', 0, '@media (max-width: 768px) applies styles only when the viewport width is 768 pixels or less.', 'Responsive Web Design') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text);
INSERT INTO questions (id, category_id, difficulty, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, topic) VALUES ('html_css_hard_21', 'html_css', 'hard', 'What creates a new Stacking Context in CSS, affecting z-index behavior?', 'position: relative with a z-index other than auto, or opacity < 1, or transform other than none', 'Any <div> with a class name', 'Only the <body> tag', 'Setting display: block', 0, 'Stacking contexts are formed by positioned elements with non-auto z-index, opacity < 1, transforms, filters, and other modern CSS properties.', 'HTML & CSS Basics') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text);
INSERT INTO questions (id, category_id, difficulty, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, topic) VALUES ('html_css_hard_22', 'html_css', 'hard', 'What is the difference between a browser Reflow (Layout) and Repaint?', 'Reflow recalculates element dimensions and positions; Repaint only redraws visual pixels without changing geometry', 'Repaint is much slower than Reflow', 'Reflow only happens when changing text color', 'They are identical browser phases', 0, 'Reflow recalculates page geometry and is computationally heavy; Repaint occurs when visual changes (like color) don''t affect layout.', 'HTML & CSS Basics') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text);
INSERT INTO questions (id, category_id, difficulty, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, topic) VALUES ('html_css_hard_23', 'html_css', 'hard', 'In CSS Grid, what is the difference between ''auto-fit'' and ''auto-fill'' in repeat()?', 'auto-fit collapses empty repeated tracks to 0px; auto-fill preserves empty tracks as distinct columns', 'auto-fill cannot be used with minmax()', 'auto-fit is only supported in Safari', 'They behave identically on mobile', 0, 'auto-fit collapses empty tracks so filled items stretch across the space; auto-fill leaves empty tracks intact.', 'CSS Grid') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text);
INSERT INTO questions (id, category_id, difficulty, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, topic) VALUES ('html_css_hard_24', 'html_css', 'hard', 'What does the ''will-change'' CSS property signal to the browser engine?', 'Hints that an element will undergo specific property changes, allowing GPU layer promotion and performance optimizations', 'Triggers a JavaScript event', 'Prevents user interaction', 'Disables responsive media queries', 0, 'will-change gives the browser advanced warning to optimize rendering (e.g., promoting to a hardware composite layer).', 'HTML & CSS Basics') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text);
INSERT INTO questions (id, category_id, difficulty, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, topic) VALUES ('html_css_hard_25', 'html_css', 'hard', 'What does the CSS ''contain: layout paint'' property do?', 'Isolates an element''s subtree from the rest of the DOM so changes inside don''t trigger reflows outside', 'Hides all overflow text', 'Prevents copying text to clipboard', 'Disables Flexbox inside', 0, 'CSS containment tells the browser that the element''s subtree is independent of the rest of the page for layout and paint.', 'HTML & CSS Basics') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text);
INSERT INTO questions (id, category_id, difficulty, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, topic) VALUES ('html_css_hard_26', 'html_css', 'hard', 'What is CSS Specificity value for: ''nav#main ul.menu li:first-child a.active''?', '1-2-3 (1 ID, 2 Classes/Pseudos, 3 Elements)', '0-3-2', '2-1-2', '0-1-4', 0, '1 ID (#main), 2 classes/pseudos (.menu, :first-child, .active = 3), and 3 elements (nav, ul, li, a = 4). Specificity is 0-1-3-4.', 'HTML & CSS Basics') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text);
INSERT INTO questions (id, category_id, difficulty, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, topic) VALUES ('html_css_hard_27', 'html_css', 'hard', 'What is the Shadow DOM in web components?', 'A scoped, encapsulated DOM tree attached to an element that isolates internal styling and script selectors', 'A 3D drop-shadow effect filter', 'A hidden iframe on the page', 'A dark-mode rendering canvas', 0, 'Shadow DOM provides true DOM and CSS scoping so internal element styles don''t leak out and global styles don''t leak in.', 'HTML & CSS Basics') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text);
INSERT INTO questions (id, category_id, difficulty, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, topic) VALUES ('html_css_hard_28', 'html_css', 'hard', 'What does ''pointer-events: none'' accomplish in CSS?', 'Makes an element invisible to mouse and touch events, passing clicks through to the underlying element', 'Hides the mouse cursor completely', 'Disables the mouse wheel', 'Prevents keyboard tab focus only', 0, 'pointer-events: none causes the element to ignore click, hover, and touch events, allowing interactions to hit elements below it.', 'HTML & CSS Basics') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text);
INSERT INTO questions (id, category_id, difficulty, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, topic) VALUES ('html_css_hard_29', 'html_css', 'hard', 'What is the critical rendering path in browser performance?', 'The sequence of steps: DOM -> CSSOM -> Render Tree -> Layout -> Paint -> Composite', 'The network route from server to DNS', 'The JavaScript compiler optimization pipeline', 'The browser cache directory structure', 0, 'The Critical Rendering Path is the sequence of steps browsers take to convert HTML, CSS, and JS into pixels on screen.', 'HTML & CSS Basics') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text);
INSERT INTO questions (id, category_id, difficulty, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, topic) VALUES ('html_css_hard_30', 'html_css', 'hard', 'Why should CSS transitions animate ''transform'' and ''opacity'' rather than ''top'', ''left'', or ''width''?', 'transform and opacity are handled entirely on the GPU composite thread without triggering CPU layout or repaint', 'transform works on older browsers only', 'top and left cannot use cubic-bezier timing', 'opacity is faster because it deletes elements', 0, 'transform and opacity skip the Layout and Paint steps and are composited directly on the GPU, avoiding jank.', 'CSS Transitions & Animations') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text);
INSERT INTO questions (id, category_id, difficulty, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, topic) VALUES ('javascript_easy_1', 'javascript', 'easy', 'Which keyword declares a reassignable, block-scoped variable in modern JavaScript?', 'var', 'let', 'const', 'static', 1, '''let'' declares a block-scoped variable whose value can be reassigned later.', 'Closures & Scope') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text);
INSERT INTO questions (id, category_id, difficulty, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, topic) VALUES ('javascript_easy_2', 'javascript', 'easy', 'What does the expression typeof ''SkillTest'' evaluate to?', '''text''', '''string''', '''String''', '''char''', 1, 'The typeof operator returns lowercase ''string'' for string values.', 'JavaScript Fundamentals') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text);
INSERT INTO questions (id, category_id, difficulty, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, topic) VALUES ('javascript_easy_3', 'javascript', 'easy', 'Which built-in method outputs messages to the browser developer console?', 'console.log()', 'print()', 'document.write()', 'terminal.print()', 0, 'console.log() writes text or objects to the web developer console.', 'JavaScript Fundamentals') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text);
INSERT INTO questions (id, category_id, difficulty, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, topic) VALUES ('javascript_easy_4', 'javascript', 'easy', 'What is the difference between == and === in JavaScript?', '== checks only value with type coercion; === checks both value and type strictly', '== checks both value and type; === checks only value', 'They are identical in modern browsers', '=== is only used for strings', 0, '=== (strict equality) tests value and type without coercion, whereas == converts types before comparing.', 'JavaScript Fundamentals') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text);
INSERT INTO questions (id, category_id, difficulty, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, topic) VALUES ('javascript_easy_5', 'javascript', 'easy', 'Which array method adds one or more elements to the end of an array?', 'push()', 'pop()', 'shift()', 'unshift()', 0, 'array.push() appends one or more items to the end of an array and returns the new length.', 'Array Methods') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text);
INSERT INTO questions (id, category_id, difficulty, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, topic) VALUES ('javascript_easy_6', 'javascript', 'easy', 'Which DOM method returns the element with the specified ID attribute?', 'document.queryId()', 'document.getElementById()', 'document.findElement()', 'document.selectId()', 1, 'document.getElementById() returns the DOM element matching the specified ID.', 'DOM Manipulation') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text);
INSERT INTO questions (id, category_id, difficulty, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, topic) VALUES ('javascript_easy_7', 'javascript', 'easy', 'What will the expression Boolean('''') (empty string) return in JavaScript?', 'true', 'false', 'undefined', 'NaN', 1, 'An empty string is a falsy value in JavaScript, so Boolean('''') returns false.', 'JavaScript Fundamentals') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text);
INSERT INTO questions (id, category_id, difficulty, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, topic) VALUES ('javascript_easy_8', 'javascript', 'easy', 'Which keyword creates a variable whose reference cannot be reassigned?', 'fixed', 'immutable', 'const', 'final', 2, '''const'' creates an immutable reference to a value that cannot be reassigned.', 'JavaScript Fundamentals') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text);
INSERT INTO questions (id, category_id, difficulty, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, topic) VALUES ('javascript_easy_9', 'javascript', 'easy', 'What is the output of 10 + ''5'' in JavaScript?', '15', '''105''', 'NaN', 'Error', 1, 'When one operand is a string, the + operator performs string concatenation, resulting in ''105''.', 'JavaScript Fundamentals') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text);
INSERT INTO questions (id, category_id, difficulty, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, topic) VALUES ('javascript_easy_10', 'javascript', 'easy', 'Which method parses a JSON string into a JavaScript object?', 'JSON.stringify()', 'JSON.parse()', 'JSON.toObject()', 'JSON.decode()', 1, 'JSON.parse() converts a valid JSON string into the corresponding JavaScript value or object.', 'JavaScript Fundamentals') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text);
INSERT INTO questions (id, category_id, difficulty, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, topic) VALUES ('javascript_medium_11', 'javascript', 'medium', 'What is a ''closure'' in JavaScript?', 'A function bundled with references to its surrounding lexical environment', 'A method that closes the browser window', 'An object with no prototype', 'A syntax error in a loop', 0, 'A closure gives an inner function access to its outer function''s scope even after the outer function has finished executing.', 'Closures & Scope') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text);
INSERT INTO questions (id, category_id, difficulty, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, topic) VALUES ('javascript_medium_12', 'javascript', 'medium', 'What is the key difference between arrow functions and regular functions regarding ''this''?', 'Arrow functions do not bind their own ''this''; they inherit ''this'' lexically from the enclosing scope', 'Arrow functions have their own dynamic ''this''', 'Arrow functions cannot take arguments', 'Regular functions cannot return values', 0, 'Arrow functions capture the ''this'' value of the enclosing execution context, unlike regular functions whose ''this'' depends on how they are called.', 'Modern ES6+') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text);
INSERT INTO questions (id, category_id, difficulty, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, topic) VALUES ('javascript_medium_13', 'javascript', 'medium', 'What does the Array.prototype.map() method return?', 'A new array containing the results of calling a provided function on every element in the calling array', 'The original array modified in place', 'A boolean indicating if elements match', 'A single accumulated number', 0, 'map() creates a brand new array populated with the results of calling a provided function on every item in the calling array.', 'Array Methods') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text);
INSERT INTO questions (id, category_id, difficulty, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, topic) VALUES ('javascript_medium_14', 'javascript', 'medium', 'What is the difference between event bubbling and event capturing in the DOM?', 'Capturing propagates from root down to target; Bubbling propagates from target up to the root', 'Bubbling only works on touchscreens', 'Capturing happens after bubbling', 'They only apply to mouse wheel events', 0, 'In DOM event propagation, capturing trickles down from the window to the target element, and bubbling then travels back up.', 'DOM Manipulation') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text);
INSERT INTO questions (id, category_id, difficulty, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, topic) VALUES ('javascript_medium_15', 'javascript', 'medium', 'What does the ''spread'' operator (...) do when applied to an array?', 'Expands an iterable array into individual elements', 'Sorts the array alphabetically', 'Reverses the array items', 'Deletes all duplicate values', 0, 'The spread operator (...) unpacks array elements or object properties into separate items or arguments.', 'Array Methods') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text);
INSERT INTO questions (id, category_id, difficulty, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, topic) VALUES ('javascript_medium_16', 'javascript', 'medium', 'What is the state of a Promise that has neither fulfilled nor rejected?', 'pending', 'settled', 'resolved', 'waiting', 0, 'A Promise is in the ''pending'' state until it either transitions to ''fulfilled'' (resolved) or ''rejected''.', 'Asynchronous JavaScript') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text);
INSERT INTO questions (id, category_id, difficulty, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, topic) VALUES ('javascript_medium_17', 'javascript', 'medium', 'What is the difference between isNaN() and Number.isNaN()?', 'isNaN() coerces values to numbers first (e.g. isNaN(''abc'') is true); Number.isNaN() checks strictly without coercion', 'They are completely identical', 'Number.isNaN() only works on negative numbers', 'isNaN() is for arrays only', 0, 'Number.isNaN() does not perform type coercion and only returns true if the argument is actually NaN and of type Number.', 'JavaScript Fundamentals') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text);
INSERT INTO questions (id, category_id, difficulty, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, topic) VALUES ('javascript_medium_18', 'javascript', 'medium', 'What is the difference between LocalStorage and SessionStorage in web browsers?', 'LocalStorage persists data with no expiration; SessionStorage clears data when the page session / tab closes', 'SessionStorage has 10x more storage capacity', 'LocalStorage is sent to the server on every HTTP request', 'SessionStorage is only accessible by server-side Node.js', 0, 'LocalStorage maintains stored data across browser restarts, whereas SessionStorage is cleared when the browser tab closes.', 'JavaScript Fundamentals') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text);
INSERT INTO questions (id, category_id, difficulty, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, topic) VALUES ('javascript_medium_19', 'javascript', 'medium', 'How does destructuring assignment work in JavaScript?', 'Unpacks properties from objects or items from arrays into distinct variables using clean syntax', 'Destroys variables to free RAM memory', 'Deletes object properties automatically', 'Serializes objects into XML', 0, 'Destructuring (e.g. const { name, age } = user) extracts values from arrays or objects into distinct variables.', 'Modern ES6+') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text);
INSERT INTO questions (id, category_id, difficulty, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, topic) VALUES ('javascript_medium_20', 'javascript', 'medium', 'What does Array.prototype.filter() do?', 'Creates a new array containing all elements that pass the test implemented by the provided function', 'Modifies elements in the array', 'Finds the first matching element only', 'Sorts the array descending', 0, 'filter() creates a shallow copy of a portion of the array with elements that return true in the callback predicate.', 'Array Methods') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text);
INSERT INTO questions (id, category_id, difficulty, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, topic) VALUES ('javascript_hard_21', 'javascript', 'hard', 'In the JavaScript Event Loop, what is the execution priority between Microtasks and Macrotasks?', 'All pending Microtasks (Promise callbacks, queueMicrotask) are executed completely before the next Macrotask (setTimeout)', 'Macrotasks always execute before any Microtasks', 'They run concurrently on two separate CPU threads', 'Microtasks are executed once every second', 0, 'The microtask queue has priority over the macrotask queue. The engine drains all microtasks before picking the next task.', 'Asynchronous JavaScript') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text);
INSERT INTO questions (id, category_id, difficulty, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, topic) VALUES ('javascript_hard_22', 'javascript', 'hard', 'What is the difference between Function.prototype.call() and Function.prototype.apply()?', 'call() accepts arguments individually separated by commas; apply() accepts arguments as an array', 'apply() runs asynchronously; call() runs synchronously', 'call() cannot change ''this''', 'apply() returns a Promise', 0, 'Both invoke the function with a given ''this'', but call() takes arguments as comma-separated values while apply() takes an array.', 'Prototypes & OOP') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text);
INSERT INTO questions (id, category_id, difficulty, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, topic) VALUES ('javascript_hard_23', 'javascript', 'hard', 'What is the key benefit of WeakMap over standard Map in JavaScript?', 'Keys must be objects, and they are weakly held, allowing garbage collection if no other references exist', 'WeakMap can store more elements than Map', 'WeakMap is thread-safe across web workers', 'WeakMap keys can be primitives like strings', 0, 'WeakMap holds weak references to its object keys, preventing memory leaks by letting the garbage collector reclaim keys.', 'Array Methods') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text);
INSERT INTO questions (id, category_id, difficulty, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, topic) VALUES ('javascript_hard_24', 'javascript', 'hard', 'What is ''Debouncing'' in JavaScript UI programming?', 'Ensuring that a function is not called until a certain amount of idle time has elapsed since its last invocation', 'Limiting execution to at most once per fixed time interval', 'A method to delete HTML buttons', 'Preventing memory leaks in canvas', 0, 'Debounce delays invoking a function until after X milliseconds have elapsed since the user last triggered it (e.g. search input).', 'JavaScript Fundamentals') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text);
INSERT INTO questions (id, category_id, difficulty, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, topic) VALUES ('javascript_hard_25', 'javascript', 'hard', 'What does the ''structuredClone()'' global method do in modern JavaScript?', 'Creates a deep clone of a given value using the structured clone algorithm', 'Performs a shallow reference copy of an object', 'Compiles JavaScript code to WebAssembly', 'Converts objects into JSON strings', 0, 'structuredClone() creates a deep copy of complex objects, properly handling circular references and nested types.', 'JavaScript Fundamentals') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text);
INSERT INTO questions (id, category_id, difficulty, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, topic) VALUES ('javascript_hard_26', 'javascript', 'hard', 'How does Prototypal Inheritance work in JavaScript?', 'Objects have an internal [[Prototype]] link; property lookups climb the chain until found or null is reached', 'Classes are copied into subclasses at compile time', 'Prototypes are stored in server database files', 'Objects inherit exclusively through Java-style interfaces', 0, 'Every JS object has a hidden link to its prototype. If a property isn''t found on the object, JS searches up the prototype chain.', 'JavaScript Fundamentals') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text);
INSERT INTO questions (id, category_id, difficulty, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, topic) VALUES ('javascript_hard_27', 'javascript', 'hard', 'What is a ''Throttling'' function used for in DOM event handlers?', 'Enforces a maximum number of times a function can be called over a given time interval (e.g. on scroll)', 'Cancels events permanently', 'Speeds up network requests', 'Freezes the user browser tab', 0, 'Throttling guarantees that a function executes at most once every N milliseconds (e.g., handling window resize or scroll).', 'DOM Manipulation') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text);
INSERT INTO questions (id, category_id, difficulty, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, topic) VALUES ('javascript_hard_28', 'javascript', 'hard', 'What is the difference between ''async/await'' and raw Promises?', 'async/await is syntactic sugar over Promises, allowing asynchronous code to be written with synchronous-like structure', 'async/await blocks the single JS thread completely', 'async functions cannot return Promises', 'Promises are deprecated in ES2020', 0, 'async/await builds on Promises to provide cleaner, more readable synchronous-looking control flow and error handling with try/catch.', 'Asynchronous JavaScript') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text);
INSERT INTO questions (id, category_id, difficulty, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, topic) VALUES ('javascript_hard_29', 'javascript', 'hard', 'What is a generator function (function*) in JavaScript?', 'A function that can be exited and later re-entered, pausing execution with the ''yield'' keyword', 'A function that generates random numbers only', 'A factory function that creates HTML elements', 'A function running inside a web worker', 0, 'Generator functions produce an iterator object and pause their execution at each ''yield'', resuming on next().', 'JavaScript Fundamentals') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text);
INSERT INTO questions (id, category_id, difficulty, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, topic) VALUES ('javascript_hard_30', 'javascript', 'hard', 'What happens if an unhandled promise rejection occurs in modern browsers?', 'Triggers the ''unhandledrejection'' event on the window and logs an error to the developer console', 'Crashes the operating system immediately', 'Silently restarts the computer', 'Deletes LocalStorage automatically', 0, 'Unhandled rejections fire an ''unhandledrejection'' event on the global window object and log an error in the console.', 'Asynchronous JavaScript') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text);